@import 'tailwindcss';

@theme {
	--color-plate: #08090c;
	--color-plate-2: #0e1015;
	--color-plate-3: #14171d;
	--color-bone: #e9e4da;
	--color-lume: #cbe7ea;
	--color-ember: #e6a45e;
	--color-ash: #7b818a;

	--font-display: 'Instrument Serif', Georgia, 'Times New Roman', serif;
	--font-sans: 'Instrument Sans', ui-sans-serif, system-ui, sans-serif;
	--font-mono: 'JetBrains Mono', ui-monospace, 'SFMono-Regular', monospace;

	--ease-expose: cubic-bezier(0.16, 1, 0.3, 1);
	--ease-state: cubic-bezier(0.4, 0, 0.2, 1);

	--text-mega: clamp(2.9rem, 11vw, 9.5rem);
	--text-huge: clamp(2.15rem, 5.8vw, 4.75rem);
	--text-big: clamp(1.55rem, 3.1vw, 2.6rem);
}

@font-face {
	font-family: 'Instrument Serif';
	src: url('/fonts/InstrumentSerif-Regular.woff2') format('woff2');
	font-weight: 400;
	font-style: normal;
	font-display: swap;
}
@font-face {
	font-family: 'Instrument Serif';
	src: url('/fonts/InstrumentSerif-Italic.woff2') format('woff2');
	font-weight: 400;
	font-style: italic;
	font-display: swap;
}
@font-face {
	font-family: 'Instrument Sans';
	src: url('/fonts/InstrumentSans-Regular.woff2') format('woff2');
	font-weight: 400;
	font-style: normal;
	font-display: swap;
}
@font-face {
	font-family: 'Instrument Sans';
	src: url('/fonts/InstrumentSans-Medium.woff2') format('woff2');
	font-weight: 500;
	font-style: normal;
	font-display: swap;
}
@font-face {
	font-family: 'JetBrains Mono';
	src: url('/fonts/JetBrainsMono-Regular.woff2') format('woff2');
	font-weight: 400;
	font-style: normal;
	font-display: swap;
}

@layer base {
	html {
		background-color: var(--color-plate);
		color: var(--color-bone);
		font-family: var(--font-sans);
		-webkit-font-smoothing: antialiased;
		scrollbar-color: var(--color-plate-3) var(--color-plate);
	}
	body {
		overflow-x: clip;
	}
	::selection {
		background-color: var(--color-lume);
		color: var(--color-plate);
	}
	:focus-visible {
		outline: 1px solid var(--color-lume);
		outline-offset: 3px;
	}
	h1,
	h2,
	h3 {
		font-family: var(--font-display);
		font-weight: 400;
		line-height: 0.94;
		letter-spacing: -0.02em;
		text-wrap: balance;
	}
	dialog::backdrop {
		background-color: color-mix(in oklab, var(--color-plate) 88%, transparent);
		backdrop-filter: blur(7px);
	}
}

@layer components {
	.grain {
		position: fixed;
		inset: 0;
		z-index: 60;
		pointer-events: none;
		opacity: 0.045;
		background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/></filter><rect width='180' height='180' filter='url(%23n)'/></svg>");
	}

	.field-dim {
		opacity: 0.06;
	}

	.field-lit {
		position: absolute;
		inset: 0;
		--r: clamp(150px, 21vw, 300px);
		-webkit-mask-image: radial-gradient(
			circle var(--r) at var(--mx, 50%) var(--my, 44%),
			#000 0%,
			#000 32%,
			transparent 72%
		);
		mask-image: radial-gradient(
			circle var(--r) at var(--mx, 50%) var(--my, 44%),
			#000 0%,
			#000 32%,
			transparent 72%
		);
	}

	[data-dev] > * {
		transition:
			opacity 900ms var(--ease-expose) calc(var(--i, 0) * 70ms),
			filter 900ms var(--ease-expose) calc(var(--i, 0) * 70ms),
			transform 900ms var(--ease-expose) calc(var(--i, 0) * 70ms);
	}
	[data-dev='0'] > * {
		opacity: 0;
		filter: blur(12px);
		transform: translateY(1rem);
	}

	.plate-img {
		filter: brightness(0.58) saturate(0.62) contrast(1.06);
		transition:
			filter 800ms var(--ease-expose),
			transform 800ms var(--ease-expose);
	}
	.plate:hover .plate-img,
	.plate:focus-visible .plate-img,
	.plate:focus-within .plate-img {
		filter: brightness(1.04) saturate(1) contrast(1);
		transform: scale(1.025);
	}

	.scan {
		position: absolute;
		inset: 0;
		pointer-events: none;
		mix-blend-mode: screen;
		opacity: 0;
		transform: translateY(-100%);
		background-image: linear-gradient(
			180deg,
			transparent 46%,
			color-mix(in oklab, var(--color-lume) 60%, transparent) 50%,
			transparent 54%
		);
	}
	.plate:hover .scan,
	.plate:focus-within .scan {
		animation: sweep 1200ms var(--ease-state);
	}

	@keyframes sweep {
		0% {
			opacity: 0;
			transform: translateY(-100%);
		}
		18% {
			opacity: 1;
		}
		82% {
			opacity: 1;
		}
		100% {
			opacity: 0;
			transform: translateY(100%);
		}
	}

	.rule {
		height: 1px;
		background-image: linear-gradient(
			90deg,
			color-mix(in oklab, var(--color-lume) 22%, transparent),
			transparent
		);
	}
}

@media (prefers-reduced-motion: reduce) {
	.field-dim {
		opacity: 0.4;
	}
	.field-lit {
		display: none;
	}
	[data-dev] > *,
	[data-dev='0'] > * {
		opacity: 1 !important;
		filter: none !important;
		transform: none !important;
		transition: none !important;
	}
	.plate-img {
		filter: brightness(0.92) saturate(0.9);
		transition: none;
	}
	.plate:hover .scan,
	.plate:focus-within .scan {
		animation: none;
	}
}

