5. CREATE src/routes/api/checkout/+server.ts with exactly this content:

import { json } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { env } from '$env/dynamic/private';
import { item } from '$lib/catalog';
import { paystack_init } from '$lib/paystack';

const mail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

export const POST: RequestHandler = async ({ request, url }) => {
	const body = await request.json().catch(() => null);
	const e = typeof body?.e === 'string' ? body.e.trim().toLowerCase() : '';
	const i = typeof body?.i === 'string' ? body.i : '';

	if (!mail.test(e)) return json({ m: 'enter a valid email' }, { status: 400 });
	const picked = item(i);
	if (!picked) return json({ m: 'that item does not exist' }, { status: 400 });

	try {
		const r = await paystack_init(
			env.PAYSTACK_SECRET_KEY,
			e,
			picked.a,
			`scn_${crypto.randomUUID().replaceAll('-', '')}`,
			`${url.origin}/r`,
			{ i }
		);
		return json({ u: r.authorization_url, k: r.access_code, r: r.reference });
	} catch {
		return json({ m: 'payment could not be started' }, { status: 502 });
	}
};

The price is NEVER taken from the request — only the item id is, and the amount comes from the
catalogue on the server. Do not add an amount field to the request body.

The reference is generated here rather than by Paystack so the same string can be used as the download
token afterwards. The `scn_` prefix makes it obvious in the Paystack dashboard.

unlock.s:
Delivery. Two routes, no database, no login, no email. Paystack is the only record of who paid, and it
is re-checked on every single request.

1. CREATE src/routes/r/+page.server.ts with exactly this content:

import { env } from '$env/dynamic/private';
import { book, item } from '$lib/catalog';
import { meta_item, paystack_verify } from '$lib/paystack';
import type { PageServerLoad } from './$types';

export const load: PageServerLoad = async ({ url, setHeaders }) => {
	setHeaders({ 'cache-control': 'private, no-store' });

	const r = url.searchParams.get('reference') ?? url.searchParams.get('trxref') ?? '';
	if (!r) return { o: null, m: 'this link carries no payment reference.' };

	const v = await paystack_verify(env.PAYSTACK_SECRET_KEY, r).catch(() => null);
	if (!v) return { o: null, m: 'we could not reach paystack to confirm this payment.' };
	if (v.status !== 'success') return { o: null, m: `paystack reports this payment as "${v.status}".` };

	const got = item(meta_item(v.metadata));
	if (!got) return { o: null, m: 'we cannot tell which books this payment was for.' };

	return {
		o: {
			r,
			e: v.customer.email,
			t: got.t,
			f: got.f.map((i) => ({ i, t: book(i)!.t }))
		},
		m: ''
	};
};

