3. CREATE src/routes/d/[r]/[f]/+server.ts with exactly this content:

import { error } from '@sveltejs/kit';
import { env } from '$env/dynamic/private';
import { book, item } from '$lib/catalog';
import { meta_item, paystack_verify } from '$lib/paystack';
import type { RequestHandler } from './$types';

export const GET: RequestHandler = async ({ params, platform }) => {
	const b = book(params.f);
	if (!b) error(404, 'no such book');

	const v = await paystack_verify(env.PAYSTACK_SECRET_KEY, params.r).catch(() => null);
	if (!v) error(502, 'could not confirm the payment');
	if (v.status !== 'success') error(403, 'this payment is not complete');
	if (!item(meta_item(v.metadata))?.f.includes(b.i)) {
		error(403, 'this payment does not include that book');
	}

	const object = await platform?.env.F.get(`${b.i}.pdf`);
	if (!object) error(404, 'that file is missing — message us on whatsapp');

	return new Response(object.body, {
		headers: {
			'content-type': 'application/pdf',
			'content-disposition': `attachment; filename="${b.i}.pdf"`,
			'cache-control': 'private, no-store'
		}
	});
};

Three things that are load-bearing and must not be "simplified":

- The download route re-verifies the reference itself. It does NOT trust that /r already did, because
  /d is reachable directly. Both routes independently ask Paystack.
- It checks membership: `item(meta_item(...)).f.includes(b.i)`. Without that line, anyone who bought the
  ₦2,500 book could edit the slug in the url and pull down the ₦12,000 one on the same reference.
- Nothing is ever read out of static/ — the PDFs only exist in the private R2 bucket bound as F.

